import itertools
import random

def get_cost(p, n):
    f = [float('inf')] * n
    l = [float('-inf')] * n
    for day, (u, v) in enumerate(p):
        day += 1
        if day < f[u]: f[u] = day
        if day < f[v]: f[v] = day
        if day > l[u]: l[u] = day
        if day > l[v]: l[v] = day
    return sum(l[i] - f[i] + 1 for i in range(n))

def solve_randomized(n, trials=50000):
    matches = list(itertools.combinations(range(n), 2))
    min_cost = float('inf')
    for _ in range(trials):
        random.shuffle(matches)
        cost = get_cost(matches, n)
        if cost < min_cost:
            min_cost = cost
    return min_cost

for n in range(2, 7):
    print(f"n={n}, min_cost={solve_randomized(n, 50000)}")

